local a=require("fcs.io.hwconfig")local b={}function b.load(c)if not fs.exists(c)or fs.isDir(c)then return nil,false,nil end;local d=fs.open(c,"r")if not d then return nil,true,"could not open"end;local e=d.readAll()d.close()local f=textutils.unserialise(e or"")if type(f)~="table"then return nil,true,"not a table"end;return f,true,nil end;function b.withDefaults(f)return a.merge(f or{},a.defaults())end;function b.save(c,f)local g=c..".tmp"local d=fs.open(g,"w")if not d then return false,"could not open tmp"end;d.write(textutils.serialise(f))d.close()if fs.exists(c)then fs.delete(c)end;fs.move(g,c)return true,nil end;return b